-- PostgreSQL
-- =====================================================================================================================
-- PRODUCTION ROLLOUT: multi-tenant partnership (Accounting module, main project v1.22.228 / accounting v1.4.21)
-- Generated by joining the individual scripts in this folder, in the order they must run. Nothing here was run on
-- production by anyone yet: read it, then run it.
--
-- HOW TO RUN
--   * AUTOCOMMIT mode, one STATEMENT at a time (in DBeaver: Ctrl+Enter on the statement, not "execute script", and no
--     manual-commit mode). A DO block counts as ONE statement: select it whole and run it as one.
--     Reason: on a busy database a long transaction piles up locks on iam_accounts / iam_users and either deadlocks
--     with live traffic or times out on lock_timeout. That already happened on dev when the file was run as a script.
--   * If a statement fails with "canceling statement due to lock timeout": nothing is half done, run that statement
--     again (they are all safe to run twice). Pausing the queue workers for a minute helps.
--   * Run STEP 0 first and read the answers.
--   * Take a backup / snapshot before STEP 1.
--
-- SAFE TO RE-RUN: STEPS 1 to 5 are idempotent (create if not exists, add column if not exists, constraints and the
-- one-time visibility backfill are guarded). STEP 6 (data fix) is idempotent as well. STEP 7 is optional.
-- =====================================================================================================================


-- SAFETY NET (run these two lines first, they only affect YOUR session):
--   * idle_in_transaction_session_timeout: if the editor leaves a transaction open (DBeaver in manual-commit mode does
--     that), the server closes the session after 2 minutes and releases its locks. Without it an open transaction that
--     altered a table blocks every query on that table until somebody presses Commit / Rollback. This already happened
--     once on production with the first run of this file. It only counts IDLE time, a long running statement is not cut.
--   * lock_timeout: a statement that cannot get its lock within 15 seconds fails (and can be run again) instead of
--     queueing behind live traffic.
set idle_in_transaction_session_timeout = '2min';
set lock_timeout = '15s';
-- DBeaver: also check that the toolbar says "Auto" commit (not "Manual") before you start.

-- =====================================================================================================================
-- STEP 0: PRE-FLIGHT (read only)
-- =====================================================================================================================

-- 0.1 The platform tenant. The scripts below use iam_accounts.id = 5 (config leo.providers.zones default).
--     This MUST be the PlusClouds account. If it is not 5 on production, change v_tenant in STEP 2 and STEP 6.
select id, uuid, name, iam_user_id from iam_accounts where id = 5;

-- 0.2 What exists already (tells you which steps were run before, nothing to decide, just read).
select 'table ' || t as object, to_regclass(t) is not null as exists
from unnest(array['accounting_partner_programs','accounting_partnership_roles','accounting_partnership_role_assignments',
                  'accounting_account_partners','accounting_partner_program_zones','accounting_partnership_zones',
                  'accounting_invoice_commissions']) as t
union all
select 'column accounting_partnerships.' || c, exists (select 1 from information_schema.columns where table_name = 'accounting_partnerships' and column_name = c)
from unnest(array['tenant_account_id','status','visibility','parent_partnership_id','path','invited_at','accepted_at']) as c
union all
select 'column accounting_accounts.tenant_account_id', exists (select 1 from information_schema.columns where table_name = 'accounting_accounts' and column_name = 'tenant_account_id')
union all
select 'constraint ' || n, exists (select 1 from pg_constraint where conname = n)
from unnest(array['chk_accounting_partnerships_status','chk_accounting_partnerships_visibility','chk_accounting_partnership_roles_rates']) as n;

-- 0.3 Duplicate partner codes would make the unique index in STEP 1 fail. Must return no rows.
select partner_code, count(*) from accounting_partnerships where deleted_at is null and partner_code is not null group by 1 having count(*) > 1;

-- 0.4 Sessions that hold locks for a long time (nothing should be listed, if something is, wait or ask who it is).
select pid, usename, state, now() - xact_start as tx_age, left(query, 80) as query
from pg_stat_activity
where datname = current_database() and xact_start is not null and now() - xact_start > interval '1 minute' and pid <> pg_backend_pid();


-- =====================================================================================================================
-- STEP 1: SCHEMA (tables, columns, indexes). Idempotent. Run statement by statement.
-- Source: 2026_11_15_multi_tenant_partnership_combined.sql, part 1
-- =====================================================================================================================
set lock_timeout = '30s';

-- Conventions: all strings are text, timestamps are timestamptz, unstructured data is json,
-- tenant = IAM account (the "program owner"), public ids are exposed as *_id by the API layer.

-- ---------------------------------------------------------------------------------------------
-- 1. Partner programs: one row per tenant (program owner). Holds branding / notification settings.
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_partner_programs
(
    id                  bigserial primary key,
    uuid                uuid                     default gen_random_uuid() not null unique,
    tenant_account_id   bigint                                             not null unique
        references iam_accounts on delete cascade,
    responsible_email   text,
    notification_webhook text,
    -- logo_url, primary_color, display_name, support_email (used by branded emails)
    branding            json,
    default_country_code text,
    max_hierarchy_depth integer                  default 3                 not null,
    status              text                     default 'active'          not null,
    iam_account_id      bigint references iam_accounts on delete set null,
    iam_user_id         bigint references iam_users on delete set null,
    created_at          timestamp with time zone default now()             not null,
    updated_at          timestamp with time zone default now()             not null,
    deleted_at          timestamp with time zone
);

comment on table accounting_partner_programs is '[label:Partner program of a tenant (program owner)]';
comment on column accounting_partner_programs.tenant_account_id is '[label:IAM account that owns the program (tenant)]';
comment on column accounting_partner_programs.branding is '[label:Branding used in emails: logo_url, primary_color, display_name, support_email]';
comment on column accounting_partner_programs.max_hierarchy_depth is '[label:Max depth of sub-partner hierarchy]';

-- ---------------------------------------------------------------------------------------------
-- 2. Generic partnership roles, defined per tenant.
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_partnership_roles
(
    id                          bigserial primary key,
    uuid                        uuid                     default gen_random_uuid() not null unique,
    tenant_account_id           bigint                                             not null
        references iam_accounts on delete cascade,
    slug                        text                                               not null,
    name                        text                                               not null,
    description                 text,
    commission_rate             numeric(8, 4)            default 0                 not null,
    -- rate earned by the parent partner when a sub-partner with this role earns commission
    parent_override_rate        numeric(8, 4)            default 0                 not null,
    commission_basis            text                     default 'invoice_amount'  not null,
    priority                    integer                  default 0                 not null,
    allows_multiple_per_customer boolean                 default false             not null,
    is_default_for_signup_code  boolean                  default false             not null,
    -- role ids (json array) a holder of this role may grant to sub-partners
    allowed_child_role_ids      json,
    -- e.g. {"can_resell":true,"can_invite_sub_partners":true}
    permissions                 json,
    status                      text                     default 'active'          not null,
    iam_account_id              bigint references iam_accounts on delete set null,
    iam_user_id                 bigint references iam_users on delete set null,
    created_at                  timestamp with time zone default now()             not null,
    updated_at                  timestamp with time zone default now()             not null,
    deleted_at                  timestamp with time zone
);

comment on table accounting_partnership_roles is '[label:Tenant defined partnership roles (distributor, reseller, ...)]';

create unique index if not exists uq_accounting_partnership_roles_tenant_slug
    on accounting_partnership_roles (tenant_account_id, slug) where (deleted_at is null);

-- ---------------------------------------------------------------------------------------------
-- 3. accounting_partnerships: tenant, invitation lifecycle, hierarchy.
--    (Table already exists in the live DB; only additive changes here.)
-- ---------------------------------------------------------------------------------------------
alter table accounting_partnerships
    add column if not exists tenant_account_id        bigint references iam_accounts on delete cascade,
    add column if not exists status                   text default 'pending' not null, -- pending|active|rejected|revoked (fail closed)
    add column if not exists invited_at               timestamp with time zone,
    add column if not exists accepted_at              timestamp with time zone,
    add column if not exists invited_by_iam_user_id   bigint references iam_users on delete set null,
    add column if not exists parent_partnership_id    bigint references accounting_partnerships on delete set null,
    add column if not exists path                     text, -- materialised path e.g. 1.5.9 (ids of ancestors + self)
    add column if not exists iam_user_id              bigint references iam_users on delete set null;

comment on column accounting_partnerships.tenant_account_id is '[label:Tenant (program owner) this partnership belongs to]';
comment on column accounting_partnerships.status is '[label:pending, active, rejected, revoked]';
comment on column accounting_partnerships.parent_partnership_id is '[label:Parent partner for sub-partners]';
comment on column accounting_partnerships.path is '[label:Materialised hierarchy path of partnership ids]';

-- partner_code is globally unique: tenant is derived from the code at signup.
create unique index if not exists uq_accounting_partnerships_partner_code
    on accounting_partnerships (partner_code) where (deleted_at is null and partner_code is not null);
create unique index if not exists uq_accounting_partnerships_tenant_account
    on accounting_partnerships (tenant_account_id, accounting_account_id) where (deleted_at is null);
create index if not exists idx_accounting_partnerships_parent
    on accounting_partnerships (parent_partnership_id) where (deleted_at is null);
create index if not exists idx_accounting_partnerships_path
    on accounting_partnerships (path text_pattern_ops) where (deleted_at is null);

-- ---------------------------------------------------------------------------------------------
-- 4. Partner <-> role assignments.
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_partnership_role_assignments
(
    id                    bigserial primary key,
    uuid                  uuid                     default gen_random_uuid() not null unique,
    tenant_account_id     bigint                                             not null
        references iam_accounts on delete cascade,
    partnership_id        bigint                                             not null
        references accounting_partnerships on delete cascade,
    partnership_role_id   bigint                                             not null
        references accounting_partnership_roles on delete cascade,
    status                text                     default 'active'          not null,
    started_at            timestamp with time zone default now()             not null,
    finished_at           timestamp with time zone,
    iam_account_id        bigint references iam_accounts on delete set null,
    iam_user_id           bigint references iam_users on delete set null,
    created_at            timestamp with time zone default now()             not null,
    updated_at            timestamp with time zone default now()             not null,
    deleted_at            timestamp with time zone
);

comment on table accounting_partnership_role_assignments is '[label:Roles held by a partner inside a tenant]';

create unique index if not exists uq_accounting_partnership_role_assignments_active
    on accounting_partnership_role_assignments (partnership_id, partnership_role_id)
    where (deleted_at is null and finished_at is null);

-- ---------------------------------------------------------------------------------------------
-- 5. Customer <-> partner link per role (replaces distributor_id / sales_partner_id /
--    integrator_partner_id / affiliate_partner_id; those stay dual-written until switch-over).
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_account_partners
(
    id                    bigserial primary key,
    uuid                  uuid                     default gen_random_uuid() not null unique,
    tenant_account_id     bigint                                             not null
        references iam_accounts on delete cascade,
    accounting_account_id bigint                                             not null
        references accounting_accounts on delete cascade,
    partnership_role_id   bigint                                             not null
        references accounting_partnership_roles on delete cascade,
    partnership_id        bigint                                             not null
        references accounting_partnerships on delete cascade,
    started_at            timestamp with time zone default now()             not null,
    finished_at           timestamp with time zone,
    iam_account_id        bigint references iam_accounts on delete set null,
    iam_user_id           bigint references iam_users on delete set null,
    created_at            timestamp with time zone default now()             not null,
    updated_at            timestamp with time zone default now()             not null,
    deleted_at            timestamp with time zone
);

comment on table accounting_account_partners is '[label:Partner serving a customer account for a given role]';

create unique index if not exists uq_accounting_account_partners_active
    on accounting_account_partners (accounting_account_id, partnership_role_id)
    where (deleted_at is null and finished_at is null);
create index if not exists idx_accounting_account_partners_partnership
    on accounting_account_partners (partnership_id) where (deleted_at is null);

-- ---------------------------------------------------------------------------------------------
-- 6. Tenant per-country default partner per role (replaces leo.providers.zones config).
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_partner_program_zones
(
    id                      bigserial primary key,
    uuid                    uuid                     default gen_random_uuid() not null unique,
    tenant_account_id       bigint                                             not null
        references iam_accounts on delete cascade,
    partner_program_id      bigint                                             not null
        references accounting_partner_programs on delete cascade,
    common_country_id       bigint,   -- null = global fallback for the role
    partnership_role_id     bigint                                             not null
        references accounting_partnership_roles on delete cascade,
    default_partnership_id  bigint                                             not null
        references accounting_partnerships on delete cascade,
    iam_account_id          bigint references iam_accounts on delete set null,
    iam_user_id             bigint references iam_users on delete set null,
    created_at              timestamp with time zone default now()             not null,
    updated_at              timestamp with time zone default now()             not null,
    deleted_at              timestamp with time zone
);

comment on table accounting_partner_program_zones is '[label:Default partner per country and role for a tenant]';

create unique index if not exists uq_accounting_partner_program_zones
    on accounting_partner_program_zones (partner_program_id, common_country_id, partnership_role_id)
    where (deleted_at is null);

-- ---------------------------------------------------------------------------------------------
-- 7. Zones a partner is responsible for.
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_partnership_zones
(
    id                  bigserial primary key,
    uuid                uuid                     default gen_random_uuid() not null unique,
    tenant_account_id   bigint                                             not null
        references iam_accounts on delete cascade,
    partnership_id      bigint                                             not null
        references accounting_partnerships on delete cascade,
    partnership_role_id bigint references accounting_partnership_roles on delete cascade, -- null = all roles of the partner
    common_country_id   bigint                                             not null,
    common_city_id      bigint,
    region              text,
    is_exclusive        boolean                  default false             not null,
    priority            integer                  default 0                 not null,
    status              text                     default 'active'          not null,
    iam_account_id      bigint references iam_accounts on delete set null,
    iam_user_id         bigint references iam_users on delete set null,
    created_at          timestamp with time zone default now()             not null,
    updated_at          timestamp with time zone default now()             not null,
    deleted_at          timestamp with time zone
);

comment on table accounting_partnership_zones is '[label:Zones (country/city) a partner is responsible for]';

create index if not exists idx_accounting_partnership_zones_lookup
    on accounting_partnership_zones (tenant_account_id, common_country_id) where (deleted_at is null);
create index if not exists idx_accounting_partnership_zones_partnership
    on accounting_partnership_zones (partnership_id) where (deleted_at is null);

-- ---------------------------------------------------------------------------------------------
-- 8. Tenant on customer accounts and on the assignment audit log.
-- ---------------------------------------------------------------------------------------------
alter table accounting_accounts
    add column if not exists tenant_account_id bigint references iam_accounts on delete set null;
comment on column accounting_accounts.tenant_account_id is '[label:Tenant (program owner) this customer belongs to]';
create index if not exists idx_accounting_accounts_tenant on accounting_accounts (tenant_account_id) where (deleted_at is null);

alter table accounting_partner_assignments
    add column if not exists tenant_account_id    bigint references iam_accounts on delete set null,
    add column if not exists partnership_role_id  bigint references accounting_partnership_roles on delete set null;
comment on column accounting_partner_assignments.partnership_role_id is '[label:Generic role of the assignment; legacy rows keep type]';

-- ---------------------------------------------------------------------------------------------
-- 9. Generic commission records (per role and hierarchy level).
-- ---------------------------------------------------------------------------------------------
create table if not exists accounting_invoice_commissions
(
    id                          bigserial primary key,
    uuid                        uuid                     default gen_random_uuid() not null unique,
    tenant_account_id           bigint                                             not null
        references iam_accounts on delete cascade,
    accounting_invoice_id       bigint                                             not null
        references accounting_invoices on delete cascade,
    partnership_role_id         bigint                                             not null
        references accounting_partnership_roles on delete cascade,
    partnership_id              bigint                                             not null
        references accounting_partnerships on delete cascade,
    level                       integer                  default 0                 not null, -- 0 = direct partner, 1 = parent override, ...
    commission_invoice_id       bigint
        references accounting_invoices on delete set null,
    iam_account_id              bigint references iam_accounts on delete set null,
    iam_user_id                 bigint references iam_users on delete set null,
    created_at                  timestamp with time zone default now()             not null,
    updated_at                  timestamp with time zone default now()             not null,
    deleted_at                  timestamp with time zone
);

comment on table accounting_invoice_commissions is '[label:Commission generated for a partner from a paid invoice]';

-- one commission per invoice/role/partner/level: makes the commission job idempotent
create unique index if not exists uq_accounting_invoice_commissions
    on accounting_invoice_commissions (accounting_invoice_id, partnership_role_id, partnership_id, level)
    where (deleted_at is null);



-- =====================================================================================================================
-- STEP 2: BACKFILL of the PlusClouds tenant (one DO block = run it whole, as one statement). Idempotent.
-- Creates the program, the 4 default roles (10% distributor / integrator / reseller, 3% affiliate), the role
-- assignments and customer links from the legacy flags and pointer columns, sets tenant on partnerships and customers.
-- Source: 2026_11_15_multi_tenant_partnership_combined.sql, part 2
-- =====================================================================================================================
-- =============================================================================================
-- PART 2: BACKFILL of the PlusClouds tenant (runs after all objects above exist).
-- Change v_tenant if the PlusClouds IAM account id is not 5 (config leo.providers.zones).
-- Single DO block = one transaction: it either completes fully or changes nothing. Safe to re-run.
-- =============================================================================================
do
$backfill$
    declare
        v_tenant constant bigint := 5; -- iam_accounts.id of the PlusClouds tenant
        v_count bigint;
    begin
        if not exists (select 1 from iam_accounts where id = v_tenant) then
            raise exception 'iam_accounts.id % does not exist, fix v_tenant', v_tenant;
        end if;

        -- 1. Program of the PlusClouds tenant.
        insert into accounting_partner_programs (tenant_account_id, responsible_email, status)
        values (v_tenant, 'tevfik.porsuk@plusclouds.com', 'active')
        on conflict (tenant_account_id) do nothing;

        -- 2. Default roles mirroring app/Enums/CommissionType.php (distributor/integrator/reseller 10%, affiliate 3%).
        --    priority mirrors the documented order Partner > Distributor > Affiliate > Sales Partner (higher = wins).
        insert into accounting_partnership_roles
            (tenant_account_id, slug, name, commission_rate, priority, is_default_for_signup_code, permissions)
        select v_tenant, r.slug, r.name, r.rate, r.priority, r.signup, r.permissions::json
        from (values ('integrator', 'Integrator', 0.10, 40, false, '{"can_resell":false,"can_invite_sub_partners":false}'),
                     ('distributor', 'Distributor', 0.10, 30, false, '{"can_resell":true,"can_invite_sub_partners":true}'),
                     ('affiliate', 'Affiliate', 0.03, 20, true, '{"can_resell":false,"can_invite_sub_partners":false}'),
                     ('reseller', 'Reseller', 0.10, 10, false, '{"can_resell":true,"can_invite_sub_partners":false}')
             ) as r(slug, name, rate, priority, signup, permissions)
        where not exists (select 1
                          from accounting_partnership_roles x
                          where x.tenant_account_id = v_tenant and x.slug = r.slug and x.deleted_at is null);

        -- 3. Every existing partnership belongs to the PlusClouds tenant and is already approved/active.
        -- Approved partnerships, or ones whose account already holds a partner role flag (that is what drives
        -- commissions today), stay active; unapproved applicants become pending. Soft-deleted rows are skipped.
        update accounting_partnerships p
        set tenant_account_id = v_tenant,
            status            = case when coalesce(p.is_approved, false)
                                          or exists (select 1 from accounting_accounts a
                                                     where a.id = p.accounting_account_id
                                                       and (a.is_distributor or a.is_integrator or a.is_reseller or a.is_affiliate))
                                     then 'active' else 'pending' end,
            path              = p.id::text
        where p.tenant_account_id is null
          and p.deleted_at is null;

        -- 4. Role flags on accounting_accounts -> role assignments (is_reseller = legacy sales partner flag).
        insert into accounting_partnership_role_assignments (tenant_account_id, partnership_id, partnership_role_id)
        select v_tenant, p.id, r.id
        from accounting_partnerships p
                 join accounting_accounts a on a.id = p.accounting_account_id
                 join accounting_partnership_roles r
                      on r.tenant_account_id = v_tenant and r.deleted_at is null
                          and ((r.slug = 'distributor' and a.is_distributor)
                              or (r.slug = 'integrator' and a.is_integrator)
                              or (r.slug = 'reseller' and a.is_reseller)
                              or (r.slug = 'affiliate' and a.is_affiliate))
        where p.deleted_at is null
          and p.status = 'active'
        on conflict do nothing;

        -- 5. Customer pointer columns -> accounting_account_partners.
        --    The pointer columns reference accounting_accounts.id (the partner's account); map to that account's partnership.
        insert into accounting_account_partners
            (tenant_account_id, accounting_account_id, partnership_role_id, partnership_id)
        select v_tenant, c.id, r.id, p.id
        from accounting_accounts c
                 cross join lateral (values ('distributor', c.distributor_id),
                                            ('reseller', c.sales_partner_id),
                                            ('integrator', c.integrator_partner_id),
                                            ('affiliate', c.affiliate_partner_id)) as v(slug, partner_account_id)
                 join accounting_partnership_roles r
                      on r.tenant_account_id = v_tenant and r.slug = v.slug and r.deleted_at is null
                 join accounting_partnerships p
                      on p.accounting_account_id = v.partner_account_id
                          and p.tenant_account_id = v_tenant and p.deleted_at is null
        where v.partner_account_id is not null
          and c.deleted_at is null
        on conflict do nothing;

        -- 6. Customers belong to the PlusClouds tenant.
        update accounting_accounts set tenant_account_id = v_tenant where tenant_account_id is null;

        -- 7. Assignment audit log: attach tenant + generic role for legacy rows.
        update accounting_partner_assignments pa
        set tenant_account_id   = v_tenant,
            partnership_role_id = r.id
        from accounting_partnership_roles r
        where pa.tenant_account_id is null
          and r.tenant_account_id = v_tenant
          and r.deleted_at is null
          and r.slug = pa.type;

        -- Summary (visible in DBeaver "Output" / psql notices)
        select count(*) into v_count from accounting_partnership_roles where tenant_account_id = v_tenant and deleted_at is null;
        raise notice 'roles: %', v_count;
        select count(*) into v_count from accounting_partnership_role_assignments where tenant_account_id = v_tenant;
        raise notice 'role assignments: %', v_count;
        select count(*) into v_count from accounting_account_partners where tenant_account_id = v_tenant;
        raise notice 'customer partner links: %', v_count;
        select count(*) into v_count from accounting_partnerships where tenant_account_id = v_tenant;
        raise notice 'partnerships in tenant: %', v_count;
    end
$backfill$;

-- Per-country defaults (leo.providers.zones) are environment specific: insert them by hand, e.g.
-- insert into accounting_partner_program_zones
--     (tenant_account_id, partner_program_id, common_country_id, partnership_role_id, default_partnership_id)
-- values (...);


-- =====================================================================================================================
-- STEP 3: STATUS HARDENING. Idempotent.
-- Source: 2026_11_16_partnership_status_hardening.sql (the constraint is guarded so it can be run twice)
-- =====================================================================================================================

-- 3.1 Unapproved partnerships without a partner flag are pending, not active. Only touches rows that never went through
--     the new invitation flow (no invited_at / accepted_at).
update accounting_partnerships p
set status = 'pending'
where p.status = 'active'
  and p.accepted_at is null
  and p.invited_at is null
  and coalesce(p.is_approved, false) = false
  and not exists (select 1
                  from accounting_accounts a
                  where a.id = p.accounting_account_id
                    and (a.is_distributor or a.is_integrator or a.is_reseller or a.is_affiliate));

-- 3.2 Role assignments must only exist for non pending partnerships.
update accounting_partnership_role_assignments ra
set finished_at = now(), status = 'inactive'
from accounting_partnerships p
where p.id = ra.partnership_id
  and p.status = 'pending'
  and ra.finished_at is null;

-- 3.3 Fail closed: new rows are pending unless the service activates them.
alter table accounting_partnerships alter column status set default 'pending';

-- 3.4 Restrict the allowed values (guarded: only added when it is not there yet), then validate.
do
$$
    begin
        if not exists (select 1 from pg_constraint where conname = 'chk_accounting_partnerships_status') then
            alter table accounting_partnerships
                add constraint chk_accounting_partnerships_status
                    check (status in ('pending', 'active', 'rejected', 'revoked')) not valid;
        end if;
    end
$$;
alter table accounting_partnerships validate constraint chk_accounting_partnerships_status;


-- =====================================================================================================================
-- STEP 4: PARTNER DIRECTORY VISIBILITY. Idempotent and ONE TIME for the data change.
-- Source: 2026_11_17_partnership_visibility.sql
-- Until now every partner was visible to every account. The partnerships that exist today are set to 'public' ONCE to
-- keep that behaviour; new partnerships start 'private'. The data change only happens when the column is created here,
-- so running this again never flips a partnership somebody made private since.
-- =====================================================================================================================
do
$$
    begin
        if not exists (select 1 from information_schema.columns
                       where table_name = 'accounting_partnerships' and column_name = 'visibility') then
            alter table accounting_partnerships add column visibility text not null default 'private';

            update accounting_partnerships
            set visibility = 'public'
            where invited_at is null
              and deleted_at is null;
        end if;
    end
$$;

comment on column accounting_partnerships.visibility is '[label:Who sees this partner in the partner lists: private, customers, public]';

do
$$
    begin
        if not exists (select 1 from pg_constraint where conname = 'chk_accounting_partnerships_visibility') then
            alter table accounting_partnerships
                add constraint chk_accounting_partnerships_visibility
                    check (visibility in ('private', 'customers', 'public')) not valid;
        end if;
    end
$$;
alter table accounting_partnerships validate constraint chk_accounting_partnerships_visibility;


-- =====================================================================================================================
-- STEP 5: COMMISSION RATE LIMITS. Idempotent.
-- Source: 2026_11_17_partnership_role_rate_limits.sql
-- =====================================================================================================================

-- 5.1 Roles that would violate the check. Must return no rows before the constraint can be validated.
select id, tenant_account_id, slug, commission_rate, parent_override_rate
from accounting_partnership_roles
where deleted_at is null
  and (commission_rate < 0 or commission_rate > 1 or parent_override_rate < 0 or parent_override_rate > 1);

-- 5.2 The check (guarded), then validate.
do
$$
    begin
        if not exists (select 1 from pg_constraint where conname = 'chk_accounting_partnership_roles_rates') then
            alter table accounting_partnership_roles
                add constraint chk_accounting_partnership_roles_rates
                    check (commission_rate between 0 and 1 and parent_override_rate between 0 and 1) not valid;
        end if;
    end
$$;
alter table accounting_partnership_roles validate constraint chk_accounting_partnership_roles_rates;


-- =====================================================================================================================
-- STEP 6: DATA CHECK AND FIX (diagnostics are read only, the DO block fixes what they show)
-- Source: 2026_11_16_multi_tenant_partnership_data_fix.sql
-- Run the diagnostics, look at the answers. Every query returns zero rows when the data is fine, EXCEPT these two which
-- are expected and explained (on dev they were: D3 = 14 customers whose partner account is not a partner, D8 = 0):
--   D3  customers pointing at an account that is not a partner (e.g. the platform account serving customers directly).
--       They get no link, the legacy pointer keeps working. Decide per account if it should become a partner.
-- Run the DO block only if D1, D2, D4, D5 or D7 show rows.
-- =====================================================================================================================
-- =============================================================================================
-- PART 1: DIAGNOSTICS (read only)
-- =============================================================================================

-- D1. Partnerships that have no tenant yet (the backfill sets it for all of them).
select id, uuid, accounting_account_id, status
from accounting_partnerships
where tenant_account_id is null
  and deleted_at is null;

-- D2. Accounts that carry a partner flag but have NO partnership row: the backfill only created role assignments for
--     existing partnership rows, so these partners are invisible to the new model and earn no commission through it.
select a.id, a.uuid, a.iam_account_id, a.is_distributor, a.is_integrator, a.is_reseller, a.is_affiliate
from accounting_accounts a
where a.deleted_at is null
  and (a.is_distributor or a.is_integrator or a.is_reseller or a.is_affiliate)
  and not exists (select 1
                  from accounting_partnerships p
                  where p.accounting_account_id = a.id
                    and p.deleted_at is null);

-- D3. Customers whose old pointer columns reference a partner account that has no (non deleted) partnership row, so
--     no accounting_account_partners link could be created for it.
select c.id as customer_id, v.slug as role_slug, v.partner_account_id
from accounting_accounts c
         cross join lateral (values ('distributor', c.distributor_id),
                                    ('reseller', c.sales_partner_id),
                                    ('integrator', c.integrator_partner_id),
                                    ('affiliate', c.affiliate_partner_id)) as v(slug, partner_account_id)
where c.deleted_at is null
  and v.partner_account_id is not null
  and not exists (select 1
                  from accounting_partnerships p
                  where p.accounting_account_id = v.partner_account_id
                    and p.deleted_at is null);

-- D4. Customers without a tenant.
select id, uuid, iam_account_id
from accounting_accounts
where tenant_account_id is null
  and deleted_at is null;

-- D5a. ACTIVE partnerships that hold no active role assignment (they exist but can earn nothing).
select p.id, p.uuid, p.accounting_account_id
from accounting_partnerships p
where p.status = 'active'
  and p.deleted_at is null
  and not exists (select 1
                  from accounting_partnership_role_assignments ra
                  where ra.partnership_id = p.id
                    and ra.deleted_at is null
                    and ra.finished_at is null
                    and ra.status = 'active');

-- D5b. Role assignments or customer links that are still open on a partnership that is NOT active.
select 'role_assignment' as kind, ra.id, ra.partnership_id, p.status
from accounting_partnership_role_assignments ra
         join accounting_partnerships p on p.id = ra.partnership_id
where ra.deleted_at is null and ra.finished_at is null and ra.status = 'active' and p.status <> 'active'
union all
select 'account_partner', ap.id, ap.partnership_id, p.status
from accounting_account_partners ap
         join accounting_partnerships p on p.id = ap.partnership_id
where ap.deleted_at is null and ap.finished_at is null and p.status <> 'active';

-- D6. Duplicate partner codes (the unique index should make this impossible; if rows show up the index is missing).
select partner_code, count(*)
from accounting_partnerships
where deleted_at is null and partner_code is not null
group by partner_code
having count(*) > 1;

-- D7. Tenant mismatches between linked rows (a role / partner / customer from another tenant).
select 'role_assignment' as kind, ra.id
from accounting_partnership_role_assignments ra
         join accounting_partnerships p on p.id = ra.partnership_id
         join accounting_partnership_roles r on r.id = ra.partnership_role_id
where ra.deleted_at is null
  and (ra.tenant_account_id <> p.tenant_account_id or ra.tenant_account_id <> r.tenant_account_id)
union all
select 'account_partner', ap.id
from accounting_account_partners ap
         join accounting_partnerships p on p.id = ap.partnership_id
         join accounting_partnership_roles r on r.id = ap.partnership_role_id
         join accounting_accounts c on c.id = ap.accounting_account_id
where ap.deleted_at is null
  and (ap.tenant_account_id <> p.tenant_account_id
    or ap.tenant_account_id <> r.tenant_account_id
    or ap.tenant_account_id <> coalesce(c.tenant_account_id, ap.tenant_account_id));

-- D8. Tenants that run a program but have no partnership role defined (they cannot invite anyone).
select pp.tenant_account_id
from accounting_partner_programs pp
where pp.deleted_at is null
  and pp.status = 'active'
  and not exists (select 1
                  from accounting_partnership_roles r
                  where r.tenant_account_id = pp.tenant_account_id
                    and r.deleted_at is null);


-- =============================================================================================
-- PART 2: FIX (one DO block = one transaction, idempotent). Review PART 1 first.
-- =============================================================================================
do
$datafix$
    declare
        v_tenant constant bigint := 5; -- iam_accounts.id of the PlusClouds tenant
        v_count bigint;
        v_account record;
    begin
        if not exists (select 1 from iam_accounts where id = v_tenant) then
            raise exception 'iam_accounts.id % does not exist, fix v_tenant', v_tenant;
        end if;

        -- F1. Partnership rows for partner flagged accounts that have none (D2). They were flagged by staff, so they
        --     are approved and active. Only the columns the application itself sets on create are filled in
        --     (see PartnershipsService::create), everything else uses the table defaults. The partner code is a
        --     random 10 character string, re-drawn until it is unused (codes are globally unique).
        for v_account in
            select a.id, a.iam_account_id
            from accounting_accounts a
            where a.deleted_at is null
              and (a.is_distributor or a.is_integrator or a.is_reseller or a.is_affiliate)
              and not exists (select 1
                              from accounting_partnerships p
                              where p.accounting_account_id = a.id and p.deleted_at is null)
            loop
                insert into accounting_partnerships
                (iam_account_id, accounting_account_id, tenant_account_id, partner_code, customer_count, level,
                 is_approved, status, accepted_at, visibility)
                select v_account.iam_account_id,
                       v_account.id,
                       v_tenant,
                       code,
                       0,
                       1,
                       true,
                       'active',
                       now(),
                       -- flagged partners were visible to everybody before the multi-tenant work: keep that
                       'public'
                from (select substr(md5(random()::text || clock_timestamp()::text || v_account.id::text), 1, 10) as code) c
                where not exists (select 1 from accounting_partnerships x where x.partner_code = c.code);
            end loop;

        -- Materialised hierarchy path for rows that have none (root partners: just their own id).
        update accounting_partnerships
        set path = id::text
        where tenant_account_id = v_tenant
          and path is null
          and deleted_at is null;

        -- F2. Customers without a tenant belong to PlusClouds (single tenant before this change).
        update accounting_accounts
        set tenant_account_id = v_tenant
        where tenant_account_id is null;

        -- F3. Role assignments for ACTIVE partnerships, from the legacy role flags (same rule as the backfill, but
        --     only active partnerships get active roles).
        insert into accounting_partnership_role_assignments (tenant_account_id, partnership_id, partnership_role_id)
        select v_tenant, p.id, r.id
        from accounting_partnerships p
                 join accounting_accounts a on a.id = p.accounting_account_id
                 join accounting_partnership_roles r
                      on r.tenant_account_id = v_tenant and r.deleted_at is null
                          and ((r.slug = 'distributor' and a.is_distributor)
                              or (r.slug = 'integrator' and a.is_integrator)
                              or (r.slug = 'reseller' and a.is_reseller)
                              or (r.slug = 'affiliate' and a.is_affiliate))
        where p.deleted_at is null
          and p.tenant_account_id = v_tenant
          and p.status = 'active'
        on conflict do nothing;

        -- F4. Customer links from the old pointer columns for partners that now have a partnership row (D3).
        insert into accounting_account_partners
            (tenant_account_id, accounting_account_id, partnership_role_id, partnership_id)
        select v_tenant, c.id, r.id, p.id
        from accounting_accounts c
                 cross join lateral (values ('distributor', c.distributor_id),
                                            ('reseller', c.sales_partner_id),
                                            ('integrator', c.integrator_partner_id),
                                            ('affiliate', c.affiliate_partner_id)) as v(slug, partner_account_id)
                 join accounting_partnership_roles r
                      on r.tenant_account_id = v_tenant and r.slug = v.slug and r.deleted_at is null
                 join accounting_partnerships p
                      on p.accounting_account_id = v.partner_account_id
                          and p.tenant_account_id = v_tenant and p.deleted_at is null and p.status = 'active'
        where v.partner_account_id is not null
          and c.deleted_at is null
        on conflict do nothing;

        -- F5. Close role assignments and customer links that are still open on a partnership that is not active (D5b).
        update accounting_partnership_role_assignments ra
        set finished_at = now(), status = 'inactive'
        from accounting_partnerships p
        where p.id = ra.partnership_id
          and p.status <> 'active'
          and ra.finished_at is null
          and ra.deleted_at is null;

        update accounting_account_partners ap
        set finished_at = now()
        from accounting_partnerships p
        where p.id = ap.partnership_id
          and p.status <> 'active'
          and ap.finished_at is null
          and ap.deleted_at is null;

        select count(*) into v_count from accounting_partnerships where tenant_account_id = v_tenant and deleted_at is null;
        raise notice 'partnerships in tenant: %', v_count;
        select count(*) into v_count from accounting_partnership_role_assignments where tenant_account_id = v_tenant and finished_at is null;
        raise notice 'open role assignments: %', v_count;
        select count(*) into v_count from accounting_account_partners where tenant_account_id = v_tenant and finished_at is null;
        raise notice 'open customer links: %', v_count;
    end
$datafix$;


-- =====================================================================================================================
-- STEP 7 (OPTIONAL): carry the real partner start dates over to the customer links
-- Source: 2026_11_17_account_partner_link_start_dates.sql
-- Only if this returns rows (the legacy assignments table has data on production). Needed so the new commission engine
-- does not skip paid invoices that the old jobs would still commission. Nothing to do on dev (the table was empty).
-- =====================================================================================================================
-- =============================================================================================
-- PART 1: DIAGNOSTICS (read only)
-- =============================================================================================

-- D1. Rows in the legacy assignment log (empty = nothing to carry over, stop here).
select type, count(*) as total, count(*) filter (where finished_at is null) as open_rows,
       min(started_at)::date as earliest, max(started_at)::date as latest
from accounting_partner_assignments
where deleted_at is null
group by type
order by type;

-- D2. Links that have a matching open legacy assignment (same customer, same role, same partner) and would change.
select r.slug, count(*) as links_to_update
from accounting_account_partners ap
         join accounting_partnership_roles r on r.id = ap.partnership_role_id
         join accounting_partnerships p on p.id = ap.partnership_id
where ap.deleted_at is null
  and ap.finished_at is null
  and exists (select 1
              from accounting_partner_assignments pa
              where pa.deleted_at is null
                and pa.finished_at is null
                and pa.accounting_account_id = ap.accounting_account_id
                and pa.type = r.slug
                and pa.new_partner_id = p.accounting_account_id
                and pa.started_at < ap.started_at)
group by r.slug
order by r.slug;


-- =============================================================================================
-- PART 2: FIX (one statement = one transaction, idempotent: only moves started_at EARLIER, never later)
-- =============================================================================================
update accounting_account_partners ap
set started_at = legacy.started_at
from (select ap2.id as link_id, min(pa.started_at) as started_at
      from accounting_account_partners ap2
               join accounting_partnership_roles r on r.id = ap2.partnership_role_id
               join accounting_partnerships p on p.id = ap2.partnership_id
               join accounting_partner_assignments pa
                    on pa.accounting_account_id = ap2.accounting_account_id
                        and pa.type = r.slug
                        and pa.new_partner_id = p.accounting_account_id
                        and pa.finished_at is null
                        and pa.deleted_at is null
      where ap2.deleted_at is null
        and ap2.finished_at is null
      group by ap2.id) legacy
where ap.id = legacy.link_id
  and legacy.started_at < ap.started_at;


-- =====================================================================================================================
-- STEP 8: VERIFY (read only). Expected after a normal rollout:
--   * the 3 constraints exist and are validated; status default is 'pending'
--   * every partnership has a tenant; no active partnership without an active role (except partners that really have none)
--   * programs >= 1, roles >= 4, open customer links > 0
-- =====================================================================================================================
select conname, convalidated from pg_constraint
where conname in ('chk_accounting_partnerships_status','chk_accounting_partnerships_visibility','chk_accounting_partnership_roles_rates') order by 1;

select column_default as status_default from information_schema.columns where table_name = 'accounting_partnerships' and column_name = 'status';

select status, visibility, is_approved, count(*) from accounting_partnerships where deleted_at is null group by 1, 2, 3 order by 1, 2, 3;

select 'programs' as what, count(*) from accounting_partner_programs where deleted_at is null
union all select 'roles', count(*) from accounting_partnership_roles where deleted_at is null
union all select 'open role assignments', count(*) from accounting_partnership_role_assignments where deleted_at is null and finished_at is null
union all select 'open customer links', count(*) from accounting_account_partners where deleted_at is null and finished_at is null
union all select 'customers without tenant', count(*) from accounting_accounts where tenant_account_id is null and deleted_at is null
union all select 'partnerships without tenant', count(*) from accounting_partnerships where tenant_account_id is null and deleted_at is null;
